{
	"name": "@rizal72/oc-plugin-updates",
	"version": "0.1.8",
	"type": "module",
	"description": "Update OpenCode plugins: one by one or all of them at once",
	"repository": {
		"type": "git",
		"url": "git+https://github.com/rizal72/opencode-plugins.git"
	},
	"license": "MIT",
	"files": [
		"*.ts",
		"!*.test.ts",
		"tui.js",
		"README.md",
		"dist"
	],
	"keywords": [
		"opencode",
		"opencode-plugin",
		"plugin-updates",
		"version"
	],
	"publishConfig": {
		"access": "public"
	},
	"exports": {
		".": "./index.ts",
		"./tui": "./tui.js",
		"./gui-experimental": "./dist/gui-experimental.cjs"
